    { name = 'Modules that change gameplay', group = 'Server', desc = 'MogHouse server notes: modules that change gameplay. Source: https://github.com/tagban/moghouse-lsb/blob/1267f7f41a/modules/init.txt https://github.com/tagban/moghouse-lsb/blob/1267f7f41a/modules/moghouse/cpp/README.md https://github.com/tagban/moghouse-lsb/blob/1267f7f41a/modules/moghouse/jump.lua https://github.com/tagban/moghouse-lsb/blob/1267f7f41a/README.md', steps = {
            { title = 'Loaded modules (modules/init.txt)', note = '• Login announcement: "Player <name> has logged in." is shown to everyone at login (not when zoning).\n• Discord bridge: Say, Shout and Yell are relayed for the Discord bot and sent to every zone, as the server settings say.\n• A test NPC in the GM home.\n• MogHouse\'s GM commands (see the Commands guide).' },
            { title = '/jump really jumps (jump.lua + jump.cpp)', note = '• The game\'s /jump normally only plays an animation; here it lifts you a little, and if there is a higher floor within 3 yalms ahead you leap onto it (a rock, a step).\n• A leap lands at most 6 yalms above where it started.\n• One jump at a time: jumps never stack into flying.' },
            { title = 'C++ helpers (modules/moghouse/cpp)', note = '• knockback.cpp: lets scripts knock a player back as mob skills do (used by !slap).\n• jump.cpp: also holds !fly fliers to the zone\'s collision, so flying through walls or the ground is refused.\n• skyfx.cpp: zone looks (aurora, wireframe, colour filter) drawn only by MogHouse\'s own client (ffxi-native); other clients see nothing new.\n• mount.cpp: lets !flymount show the mount; MogHouse\'s own mounts (bee, airship, boat) are seen by other clients as a retail mount.' },
